// The session reports its own state (issue #1336, EPIC #1334 C2).
//
// Until now `@claude_state` came from settings hooks (PreToolUse / PostToolUse /
// Stop / Notification) plus a screen classifier that read the pane with a model
// call to tell `done` from "waiting on you" and "a Loop is pending". The engine
// knows all three outright, so the mod says them as they happen:
//
//   turn.start              → working
//   turn.complete           → done, or `looping` when @loop says a Loop is pending
//   tool.call AskUserQuestion → needs/ask while the question is open, working after
//   tool.call ScheduleWakeup | CronCreate | CronDelete → @loop, after the call
//
// Every write goes through the fleet's own writers, never a tmux call of ours:
// bin/set-claude-state.sh (`--via mod`: the state write alone — the Stop hook keeps
// the auto-handoff / compaction / parent-report side of a clean stop) and
// bin/fleet_loop_mark.py's PostToolUse entry, fed the same payload the hook gets, so
// whichever of the two writers arrives first, @loop reads the same. The settings
// hooks are not removed: they still fire, and write the same values.
//
// With the mod alive (bin/fleet-lib.sh fleet_mod_alive) the screen classifier skips
// the window (`skip:mod` in classify.log, bin/classify-sessions.sh). Subagent turns
// and calls (`agentId`) are not this pane's state and are passed straight on.

import type { EngineInterface, On } from 'claude-code'

import { isOpen } from './gate'

/** How long one fleet-script write may take before it is abandoned. */
export const WRITE_TIMEOUT_MS = 10_000

const LOOP_TOOLS = new Set(['ScheduleWakeup', 'CronCreate', 'CronDelete'])

/** The fleet's bin/ beside this plugin (<install>/mod/fleet → <install>/bin), or
 * undefined outside tmux, where there is no window to write. */
async function fleetBin($: EngineInterface): Promise<string | undefined> {
  const pane = await $.env.get('TMUX_PANE')
  if (pane === undefined || pane === '') return undefined
  return `${$.plugin.root}/../../bin`
}

/** `set-claude-state.sh --via mod <verb>`; a failed write leaves the hooks' value.
 * `stdin`: the hook payload's shape, for a verb that reads one (`ask`'s question). */
async function setState($: EngineInterface, verb: 'working' | 'done' | 'ask', stdin = ''): Promise<void> {
  try {
    const bin = await fleetBin($)
    if (bin === undefined) return
    await $.process.run(['sh', `${bin}/set-claude-state.sh`, '--via', 'mod', verb], {
      stdin,
      timeoutMs: WRITE_TIMEOUT_MS,
    })
  } catch {
    // The settings hooks still write the same state; nothing to undo.
  }
}

/** Hand fleet_loop_mark.py the PostToolUse payload of a Loop tool call. */
async function markLoop($: EngineInterface, payload: Record<string, unknown>): Promise<void> {
  try {
    const bin = await fleetBin($)
    if (bin === undefined) return
    await $.process.run(['python3', `${bin}/fleet_loop_mark.py`, 'hook'], {
      stdin: JSON.stringify(payload),
      timeoutMs: WRITE_TIMEOUT_MS,
    })
  } catch {
    // The PostToolUse hook writes the same @loop.
  }
}

/** The tool's own arguments: the call's input minus the envelope keys. */
function toolInput(e: Record<string, unknown>): Record<string, unknown> {
  const { tool: _t, tool_use_id: _id, agentId: _a, consent: _c, ...rest } = e
  return rest
}

export function registerState(on: On): void {
  on('turn.start', async ($, e, next) => {
    if (isOpen()) await setState($, 'working')
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    // set-claude-state.sh's done branch turns this into `looping` when @loop (or a
    // loop ledger) says a Loop is pending — the one place that decides it.
    if (isOpen() && e.agentId === undefined) await setState($, 'done')
    return result
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    if (!isOpen() || e.agentId !== undefined) return next(e)
    // The question's own words ride along (issue #1951): @claude_needs_detail.
    await setState($, 'ask', JSON.stringify({ tool_name: 'AskUserQuestion', tool_input: toolInput(e) }))
    try {
      return await next(e)
    } finally {
      // Answered, declined or interrupted: the question is no longer open.
      await setState($, 'working')
    }
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    if (!isOpen() || e.agentId !== undefined || !LOOP_TOOLS.has(e.tool)) return next(e)
    const result = await next(e)
    if (result.deny === undefined && !result.isError) {
      await markLoop($, {
        tool_name: e.tool,
        tool_input: toolInput(e as unknown as Record<string, unknown>),
        tool_response: result.result,
      })
    }
    return result
  }).catch(($, e, next) => next(e))
}

files.hooks/tools.ts:
// The fleet's three in-session tools, kept as the FALLBACK for a session launched
// before the fleet tool service (issue #2057; the tools: issue #1340, retired as
// the primary road in #1812).
//
//   mcp__fleet__fleet_status / mcp__fleet__fleet_spawn / mcp__fleet__fleet_await
//
// bin/fleet-claude.sh mounts bin/fleet-mcp.py as the MCP server `fleet` on every
// new session and exports FLEET_MCP_SERVER=1 (issue #1807): there the mod registers
// NOTHING — status / spawn / await are the service's own tools. A session launched
// before that (`--plugin-dir` only, no `--mcp-config`) has no service, and its tool
// list — registered once at ITS start — still carries the mod's three: a hot reload
// swaps the code, never the list. Mod 0.4.0 dropped the handler, so every such call
// died with «no tool.call hook answered». Hence, one implementation, two roads:
//
//   - registration (lifecycle.ts onReady, FLEET_MCP_SERVER not 1 — the engine
//     follows `$` only within one file, so the run lives there and the argv and
//     the parse live here): the three are registered from the SERVICE's own specs
//     — `fleet-mcp.py --spec status spawn await` — so a schema lives once; a
//     re-register on a reload costs nothing;
//   - serving (the tool.call hook below): every call is forwarded to `fleet-mcp.py
//     --call <tool> <json>` — the same identity check, argument check, repo check,
//     script run and call log (road=call) as a tools/call. This file knows the
//     argv and the timeout, no more: nothing here parses an argument or names a
//     script;
//   - the retreat (the issue's B): when the FORWARD itself fails — no python3, the
//     install's bin/ gone, a usage exit, a timeout — the answer is one actionable
//     message: reopen the session (/fleet-handoff, or `claude --resume`) so it
//     mounts the service, or run the script by hand meanwhile.

import type { On, ToolSpec } from 'claude-code'

import { isOpen } from './gate'

export const PLUGIN = 'fleet'
// FLEET_MCP_SERVER=1 (set by bin/fleet-claude.sh, #1807) says the service is
// mounted; lifecycle.ts reads it by its literal name, as the engine requires.
// bin/fleet-oldcfg-replay.py reads the two below (issue #2075): FALLBACK is «the tools
// this version registers», TOOL_RE «the names the tool.call hook answers». Rename
// either and teach the replay the new spelling, or the release gate goes red.
/** The service's tools the fallback carries, in registration order. */
export const FALLBACK = ['status', 'spawn', 'await'] as const
export type Fallback = (typeof FALLBACK)[number]

/** Every tool this file serves, as the model calls it. */
export const TOOL_RE = /^mcp__fleet__fleet_(status|spawn|await)$/

// Timeouts stand a little past fleet-mcp.py's own (SPAWN_TIMEOUT_S 120, STATUS 30,
// await = timeout + 25), so the service's «did not answer within» is what the model
// reads, not a cut from here; `$.process.run` allows ten minutes at most.
export const AWAIT_DEFAULT_S = 540
const AWAIT_SLACK_S = 25
const HEADROOM_S = 10
export const SPEC_TIMEOUT_MS = 30_000
export const STATUS_TIMEOUT_MS = (3 * 30 + HEADROOM_S) * 1000
export const SPAWN_TIMEOUT_MS = (120 + HEADROOM_S) * 1000
export const RUN_MAX_MS = 600_000

/** The install's bin/, from the plugin root (<install>/mod/fleet). */
export function binDir(root: string): string {
  const base = root.replace(/\/+$/, '').replace(/\/\.claude-plugin$/, '')
  return `${base}/../../bin`
}

function service(bin: string): string[] {
  return ['python3', `${bin}/fleet-mcp.py`]
}

/** The argv that prints the three specs. */
export function specArgv(bin: string): string[] {
  return [...service(bin), '--spec', ...FALLBACK]
}

/** The argv that makes one call — the arguments travel as one JSON word. */
export function callArgv(bin: string, tool: string, args: Record<string, unknown>): string[] {
  return [...service(bin), '--call', tool, JSON.stringify(args)]
}

/** True for a run of this file's (a test's recorder filters them, like where.ts's). */
export function isToolsRun(argv: readonly string[]): boolean {
  return argv[0] === 'python3' && (argv[1] ?? '').endsWith('/fleet-mcp.py')
}

/** How long a forwarded call may take, by tool (await: its own timeout + slack). */
export function timeoutFor(tool: string, args: Record<string, unknown>): number {
  if (tool === 'await') {
    const t = typeof args.timeout === 'number' ? args.timeout : AWAIT_DEFAULT_S
    return Math.min(RUN_MAX_MS, (t + AWAIT_SLACK_S + HEADROOM_S) * 1000)
  }
  return tool === 'spawn' ? SPAWN_TIMEOUT_MS : STATUS_TIMEOUT_MS
}

const NOTE =
  '[fallback — this session was launched before the fleet tool service; the call is forwarded to ' +
  'bin/fleet-mcp.py. A reopened session (/fleet-handoff, or claude --resume) has the service\'s own tools.] '

/** The `--spec` output as the tools to register: `fleet_` + name, the note, the schema as is. */
export function fallbackSpecs(stdout: string): ToolSpec[] {
  const rows = JSON.parse(stdout) as unknown
  if (!Array.isArray(rows)) throw new Error('--spec did not print a list')
  return rows.map(row => {
    const r = row as { name?: unknown; description?: unknown; inputSchema?: unknown }
    if (typeof r.name !== 'string' || r.inputSchema === undefined) throw new Error('--spec row without name/schema')
    return {
      name: `fleet_${r.name}`,
      description: NOTE + (typeof r.description === 'string' ? r.description : ''),
      inputSchema: r.inputSchema,
    } as ToolSpec
  })
}

/** The one message when the forward itself cannot run (the issue's B). */
export function unreachable(full: string, tool: string, detail: string): string {
  const script =
    tool === 'spawn' ? 'dash-issue-session.sh <N> --repo <owner/name>'
    : tool === 'await' ? 'fleet-await.sh <N> --repo <owner/name>'
    : 'fleet-children.sh'
  return [
    `${full}: 这个会话启动于 fleet 工具服务（bin/fleet-mcp.py）之前，mod 的兜底转调失败：${detail}。`,
    '请 /fleet-handoff，或退出后用 `claude --resume` 重开 — 新会话挂上 fleet 工具服务（mcp__fleet__status / spawn / await）。',
    `临时可以用 Bash 调 ~/.claude/fleet/bin/${script}。`,
  ].join('\n')
}

const RESERVED = new Set(['tool', 'tool_use_id', 'agentId', 'consent'])

function argsOf(e: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(e)) if (!RESERVED.has(k)) out[k] = v
  return out
}

export function registerTools(on: On): void {
  // Unconditional past the gate: a call arrives only where a tool is listed, and
  // that list is the session's own — so answer it, served or not.
  on('tool.call', { tool: TOOL_RE }, async ($, e, next) => {
    const full = String(e.tool)
    const m = TOOL_RE.exec(full)
    if (!isOpen() || m === null) return next(e)
    const tool = m[1] as Fallback
    const args = argsOf(e as unknown as Record<string, unknown>)
    try {
      const r = await $.process.run(callArgv(binDir($.plugin.root), tool, args), { timeoutMs: timeoutFor(tool, args) })
      const text = r.stdout.replace(/\s+$/, '')
      if (r.exitCode === 0) return { result: text }
      if (r.exitCode === 1 && text !== '') return { deny: text }   // the service refused or faulted, with its reason
      const err = r.stderr.replace(/\s+$/, '')
      return { result: unreachable(full, tool, `fleet-mcp.py --call exited ${r.exitCode}${err ? ` (${err})` : ''}`) }
    } catch (err) {
      // No python3, no bin/, a timeout: say what to do, never hang.
      return { result: unreachable(full, tool, err instanceof Error ? err.message : String(err)) }
    }
  }).catch(($, e, next) => next(e))
}

files.hooks/usage.ts:
// Context, quota, model and effort, reported by the session itself (issue #1338,
// EPIC #1334; model/effort + the bus feed, issue #1459).
//
// The engine pushes `session.measure` after every main-thread turn and when a
// rate-limit window moves a whole point — rendered or not, watched or not. So a
// background window nobody looks at still reports, where Claude Code's status
// line (conf/statusline.sh) only runs when the status line redraws — and once a
// login turns that status line OFF (`bin/fleet-statusline.sh off`, which gives the
// pane its bottom row back) this is the ONLY reporter.
//
// One writer: everything here goes through conf/statusline.sh itself, run as
//
//   bash <install>/conf/statusline.sh --from mod key=value …
//
// so the window options, their rounding and the @ctx_band thresholds are that
// one file's whoever feeds it — Claude Code's JSON or this mod's argv. The
// options it stamps for us:
//
//   @ctx_pct @ctx_limit @ctx_band  the context fill (integer %), window size and
//                                  the fleet's handoff band (fleet-context.sh, the
//                                  auto-handoff nudge, the pane header's colour)
//   @ctx_src mod                   this mod fed the bus at least once; the Claude
//                                  path never touches it, so a window keeps the
//                                  mark — fleet-statusline.sh counts them
//   @model @effort                 the model's display name and effort level (the
//                                  pane header; fleet-model-switch.sh verifies a
//                                  /model off @model, so it must flip without a
//                                  turn — hence the poll)
//   @rl5h @rl7d @rl_reset @rl_ts   the account's 5h/7d % used and resets (issue
//   @rl_src mod                    #1267; a fresh `mod` stamp lets the quota watch
//                                  skip its ccquota fetch, bin/fleet-quotawatch.sh)
//
// Three sources, one target:
//   session.measure  context + rate limits, when `changed` names either (here)
//   turn.step        the model id and effort of each main-thread model request,
//                    fed only when the pair changed — observe-and-pass, the
//                    stream is never held for the write (here)
//   a 2 s poll       `$.session.model()`, run by lifecycle.ts's onReady timer
//                    (the engine follows `$` only within one file), so a /model
//                    typed or posted lands on the bus within ~2 s and
//                    fleet-model-switch's 15 s verify reads it. It feeds the
//                    model alone — the script unsets @effort, and the next
//                    turn.step restores the new model's.
// The model dedup (`claimModelFeed`) is shared by the two model sources so a
// pair is fed once. Rate limits are stamped only when BOTH windows have a
// reading — the watch reads a half stamp as none; the script enforces that too.

import type { EngineInterface, On, SessionMeasureInput, TurnStepInput } from 'claude-code'

import { isOpen } from './gate'

/** One bash + awk + tmux chain; well under the hook's budget. */
export const STATUSLINE_TIMEOUT_MS = 10_000
/** How often lifecycle.ts re-reads the live model while nothing else reports it. */
export const MODEL_POLL_MS = 2_000

/** <install>/conf/statusline.sh from the plugin root (<install>/mod/fleet). */
export function statuslinePath(root: string): string {
  const base = root.replace(/\/+$/, '').replace(/\/\.claude-plugin$/, '')
  return `${base}/../../conf/statusline.sh`
}

/** The argv that feeds `fields` to the bus through the script. */
export function feedArgv(root: string, fields: readonly string[]): string[] {
  return ['bash', statuslinePath(root), '--from', 'mod', ...fields]
}

/**
 * Claude Code's display name for a model id, as its status line spells it:
 * `claude-opus-5-5` → `Opus 5.5`, `claude-haiku-4-5-20251001` → `Haiku 4.5`,
 * `claude-sonnet-4-6[1m]` → `Sonnet 4.6 (1M context)`. An id outside that
 * grammar (a Bedrock arn, an alias) is shown as it is — fleet-model-switch's
 * match is a case-insensitive substring either way.
 */
export function displayName(id: string): string {
  const raw = id.trim()
  const m = /^claude-([a-z]+)-(\d+)-(\d+)(?:-\d{6,})?(\[1m\])?$/i.exec(raw)
  if (m === null) return raw
  const family = m[1]!.charAt(0).toUpperCase() + m[1]!.slice(1).toLowerCase()
  return `${family} ${m[2]}.${m[3]}${m[4] ? ' (1M context)' : ''}`
}

/** ISO 8601 → epoch seconds as a string; `-` when absent or unreadable. */
function epoch(iso: string | undefined): string {
  const ms = iso === undefined ? NaN : Date.parse(iso)
  return Number.isFinite(ms) ? String(Math.floor(ms / 1000)) : '-'
}

/** The key=value fields one measurement feeds the bus; empty when it carries nothing to say. */
export function measureFields(e: Pick<SessionMeasureInput, 'context' | 'rateLimits'>): string[] {
  const out: string[] = []
  const { percent, window } = e.context
  if (percent !== undefined && Number.isFinite(percent)) {
    // Raw, to two decimals: the script rounds it (printf %.0f) as it rounds Claude's.
    out.push(`ctx_pct=${percent.toFixed(2)}`)
    if (Number.isFinite(window) && window > 0) out.push(`ctx_limit=${Math.floor(window)}`)
  }
  const five = e.rateLimits.find(r => r.kind === 'five_hour')
  const seven = e.rateLimits.find(r => r.kind === 'seven_day')
  if (five !== undefined && seven !== undefined && Number.isFinite(five.percentUsed) && Number.isFinite(seven.percentUsed)) {
    out.push(`rl5h=${Math.max(0, Math.floor(five.percentUsed))}`)
    out.push(`rl7d=${Math.max(0, Math.floor(seven.percentUsed))}`)
    out.push(`rl_reset5=${epoch(five.resetsAt)}`)
    out.push(`rl_reset7=${epoch(seven.resetsAt)}`)
  }
  return out
}

/** The key=value fields for a model (+ its effort; none ⇒ the script unsets @effort). */
export function modelFields(id: string, effort: string | number | undefined): string[] {
  const out = [`model=${displayName(id)}`]
  if (effort !== undefined && effort !== '') out.push(`effort=${effort}`)
  return out
}

// --- the model dedup, shared by turn.step (here) and the poll (lifecycle.ts) ---
// Module state: a reload is a fresh module and session.start fires again.
let fedModel: { id: string; effort: string } | undefined

/** Forget what was fed (session.start, or a feed that failed — the next source retries). */
export function resetModelFeed(): void {
  fedModel = undefined
}

/** True when `id` is not the model last fed (the poll's question). */
export function modelMoved(id: string): boolean {
  return id !== '' && fedModel?.id !== id
}

/**
 * Record (id, effort) as fed and return its fields — or null when that pair is
 * what the bus already has, or `id` is empty.
 */
export function claimModelFeed(id: string, effort: string | number | undefined): string[] | null {
  if (id === '') return null
  const eff = effort === undefined ? '' : String(effort)
  if (fedModel !== undefined && fedModel.id === id && fedModel.effort === eff) return null
  fedModel = { id, effort: eff }
  return modelFields(id, effort)
}

async function feed($: EngineInterface, fields: readonly string[]): Promise<void> {
  if (fields.length === 0) return
  const pane = await $.env.get('TMUX_PANE')
  if (pane === undefined || pane === '') return
  await $.process.run(feedArgv($.plugin.root, fields), { timeoutMs: STATUSLINE_TIMEOUT_MS })
}

async function feedStep($: EngineInterface, e: TurnStepInput): Promise<void> {
  const fields = claimModelFeed(e.model, e.effort)
  if (fields === null) return
  try {
    await feed($, fields)
  } catch {
    resetModelFeed()
  }
}

export function registerUsage(on: On): void {
  on('session.measure', async ($, e, next) => {
    if (!isOpen()) return next(e)
    if (e.changed.includes('context') || e.changed.includes('rateLimits')) {
      try {
        await feed($, measureFields(e))
      } catch {
        // A missed report leaves the last one standing; the next measurement writes.
      }
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.step', async function* ($, e, next) {
    // Observe and pass: the write runs beside the stream, never ahead of it.
    if (isOpen() && e.agentId === undefined) void feedStep($, e)
    return yield* next(e)
  }).catch(async function* ($, e, next) {
    return yield* next(e)
  })
}

files.hooks/gate.ts:
// The one switch every fleet hook stands behind (EPIC #1334 rule 5).
//
// `register` runs before the engine can say its version, so a feature file
// cannot simply skip registering. lifecycle.ts's session.start hook checks the
// version and opens the gate when it is in range, so:
//
//   - an ordinary hook starts with `if (!isOpen()) return next(e)` and passes
//     straight through to the engine while the gate is shut;
//   - work that needs the session up (a timer, a first write) goes in
//     lifecycle.ts's `onReady`, which runs only once the gate is open — the
//     engine takes one unmatched session.start hook per plugin.
//
// `$` is never handed across an import (the engine follows it only within one
// file), so this file holds the flag and nothing else. A reload is a fresh
// module: the gate starts shut and session.start fires again.

let open = false

export function isOpen(): boolean {
  return open
}

/** lifecycle.ts only: the version check passed. */
export function openGate(): void {
  open = true
}

files.hooks/orchestrator.ts:
// The orchestrator's role, in every request (issue #2582, EPIC #2581 C1).
//
// The fleet's one orchestrating session (bin/fleet-orchestrator.sh) used to know
// what it was from one seed turn, `/fleet-orchestrate` — a compaction kept only a
// summary of it, a /clear nothing at all. Its role now rides the system prompt
// two ways from ONE file, skills/fleet-orchestrate/role.md: the launcher's
// `--append-system-prompt-file`, and this `session` section, so a session the
// launcher did not start (a hand `claude --resume`, a handoff) still carries it.
//
// lifecycle.ts reads the window's `@fleet_role` and the file once at the start
// (the run and `$` live there: the engine follows `$` only within one file); a
// window that is not `orchestrator`, or a file that cannot be read, adds nothing;
// compose.ts adds the section.
// A worker window never sees this section. The same read says whether this is
// the orchestrator's window at all (isOrchestrator), which exit-guard.ts asks.

import type { PromptComposeSection } from 'claude-code'

export const ROLE_SECTION = 'fleet:orchestrator-role'

let role: string | undefined
let orchestrator = false

/** <install>/skills/fleet-orchestrate/role.md from the plugin root (<install>/mod/fleet). */
export function rolePath(root: string): string {
  const base = root.replace(/\/+$/, '').replace(/\/\.claude-plugin$/, '')
  return `${base}/../../skills/fleet-orchestrate/role.md`
}

/** The argv that prints this pane's window's `@fleet_role`. */
export function roleArgv(pane: string): string[] {
  return ['tmux', 'display-message', '-p', '-t', pane, '#{@fleet_role}']
}

/**
 * Take the start-up read: the window's role and the file's text. Only an
 * `orchestrator` window with a non-empty file keeps a role; anything else
 * clears it.
 */
export function takeRole(windowRole: string, text: string | undefined): void {
  const body = text?.trim() ?? ''
  orchestrator = windowRole.trim() === 'orchestrator'
  role = orchestrator && body !== '' ? body : undefined
}

export function currentRole(): string | undefined {
  return role
}

/** Is this the orchestrator's window — with or without its role file (exit-guard.ts, #2584)? */
export function isOrchestrator(): boolean {
  return orchestrator
}

/** Tests: forget the role. */
export function resetRole(): void {
  role = undefined
  orchestrator = false
}

export function roleSection(text: string): PromptComposeSection {
  return { id: ROLE_SECTION, scope: 'session', text }
}

/** Tests: is this argv the role read? */
export function isRoleRun(argv: readonly string[]): boolean {
  return argv[0] === 'tmux' && argv[1] === 'display-message' && argv[argv.length - 1] === '#{@fleet_role}'
}

files.hooks/where.ts:
// Where the person is (issue #1716, EPIC #1710 C6): one line in the session's
// context — 「操作者此刻在：MacBook · macOS · iTerm2 3.6 · 能：打开网页…」 — so a
// session on any machine knows which device and terminal the person uses right
// now, and what it can do for them there.
//
// The line comes from bin/fleet-client-where.sh, THE one reader (EPIC rule 7):
// the hub's client lease, or with no hub the fleet-shell client attached here.
// lifecycle.ts reads it at the start and every WHERE_POLL_MS (the timer and `$`
// live there: the engine follows `$` only within one file); compose.ts's
// `prompt.compose` hook adds it as the last `session` section, so a takeover (the phone
// opening the client) reaches the model's next request within the poll. A read
// that fails keeps the last line; no line yet adds nothing.

import type { PromptComposeSection } from 'claude-code'

export const WHERE_POLL_MS = 15_000
/** The script asks the hub (≤5 s) and maybe tmux; well inside this. */
export const WHERE_TIMEOUT_MS = 10_000
export const WHERE_SECTION = 'fleet:where'

let line: string | undefined

/** <install>/bin/fleet-client-where.sh from the plugin root (<install>/mod/fleet). */
export function whereArgv(root: string): string[] {
  const base = root.replace(/\/+$/, '').replace(/\/\.claude-plugin$/, '')
  return ['bash', `${base}/../../bin/fleet-client-where.sh`]
}

/**
 * Take one run of the script: exit 0 names a client, 3 says nobody is
 * connected; anything else is no answer and keeps what we had. Returns true
 * when the line changed.
 */
export function takeWhere(exitCode: number, stdout: string): boolean {
  if (exitCode !== 0 && exitCode !== 3) return false
  const next = stdout.split('\n')[0]?.trim() ?? ''
  if (next === '' || next === line) return false
  line = next
  return true
}

export function currentWhere(): string | undefined {
  return line
}

/** Tests: forget the line. */
export function resetWhere(): void {
  line = undefined
}

export function whereSection(text: string): PromptComposeSection {
  return {
    id: WHERE_SECTION,
    scope: 'session',
    text:
      `# 操作者此刻在哪\n操作者此刻在：${text}\n` +
      '（fleet 客户端租约；换设备接管后这一行会跟着变。要最新的或要字段，运行 ' +
      '`~/.claude/fleet/bin/fleet-client-where.sh [--json]`；给操作者看网页/文件前按这里的「能：」选送达方式，不要自己猜终端或设备。）',
  }
}

/** Tests: is this argv the where read (so a test counting its own runs can skip it)? */
export function isWhereRun(argv: readonly string[]): boolean {
  return argv[0] === 'bash' && (argv[1] ?? '').endsWith('/bin/fleet-client-where.sh')
}

files.hooks/inbox.ts:
// The pane's command inbox (issue #1337, EPIC #1334 C3).
//
// The fleet used to TYPE `/clear`, `/compact …`, `/model …` and the handoff
// pickup into a pane (Escape, the text, a separate Enter, then poll the screen).
// Now bash posts the command as a file (bin/fleet-lib.sh fleet_session_command)
// and this mod runs it with `$.command.run`, which the engine queues until the
// session is idle — never mid-turn, never glued onto a half-typed draft.
//
//   <FLEET_CONF_DIR>/global/mod-inbox/<socket-label>/<pane-id>/
//     <seq>.json   {"cmd":"/clear","args":"","from":"handoff-cycle"}
//     <seq>.taken  our claim: an atomic `mv` of the .json — the poster cancels with
//                  the same rename, so exactly one side ever wins
//     <seq>.done   {"ok":true} | {"ok":false,"error":"…"}
//
// The poll runs on lifecycle.ts's timer, not on a session event: a /clear ends
// the session and fires no new session.start, but the module and its timers go
// on — so the pickup posted right after a handoff's /clear is still taken.
// `$` is never handed across an import (gate.ts), so lifecycle.ts hands this
// file an `InboxIo` built from its own `$` calls; everything here is plain logic.

/** The poll interval (ms). */
export const INBOX_MS = 1000

/** One posted command. */
export type InboxMessage = { cmd: string; args: string; from: string }

/** The `$` calls one poll needs, bound by lifecycle.ts. */
export type InboxIo = {
  list: (dir: string) => Promise<string[]>
  read: (path: string) => Promise<string>
  write: (path: string, text: string) => Promise<void>
  /** Atomic rename; false when the source is gone (the poster cancelled it). */
  claim: (from: string, to: string) => Promise<boolean>
  run: (command: string, args: string) => Promise<void>
}

/**
 * The inbox directory for this pane, or undefined outside tmux. `tmux` is $TMUX
 * (`<socket path>,<pid>,<session>`); the socket's basename is the fleet's label —
 * a pane id is unique per server only, and every fleet runs its own (#159).
 */
export function inboxDir(confDir: string, tmux: string | undefined, pane: string | undefined): string | undefined {
  if (!tmux || !pane || !/^%\d+$/.test(pane)) return undefined
  const sock = tmux.split(',')[0]?.split('/').pop() ?? ''
  if (sock === '') return undefined
  return `${confDir.replace(/\/+$/, '')}/global/mod-inbox/${sock}/${pane.slice(1)}`
}

/** A posted file's message, or a reason it cannot run. */
export function parseMessage(text: string): InboxMessage | { error: string } {
  let v: unknown
  try {
    v = JSON.parse(text)
  } catch {
    return { error: 'not JSON' }
  }
  if (typeof v !== 'object' || v === null) return { error: 'not an object' }
  const o = v as Record<string, unknown>
  const cmd = typeof o.cmd === 'string' ? o.cmd.trim() : ''
  if (!/^\/[^\s/][^\s]*$/.test(cmd)) return { error: 'cmd must be one /command' }
  return {
    cmd: cmd.slice(1),
    args: typeof o.args === 'string' ? o.args : '',
    from: typeof o.from === 'string' ? o.from : '?',
  }
}

/** Pending seqs, oldest first (seqs start with the epoch second). */
export function pending(names: readonly string[]): string[] {
  return names
    .filter(n => n.endsWith('.json') && !n.startsWith('.'))
    .map(n => n.slice(0, -'.json'.length))
    .sort()
}

function errorText(err: unknown): string {
  const s = err instanceof Error ? err.message : String(err)
  return s.replace(/\s+/g, ' ').slice(0, 300)
}

/**
 * One poll: claim each pending command, run it, write its .done. Commands run
 * one at a time, in post order; `$.command.run` itself waits for an idle session.
 */
export async function pollInbox(io: InboxIo, dir: string): Promise<number> {
  let names: string[]
  try {
    names = await io.list(dir)
  } catch {
    return 0 // no inbox yet: nothing was ever posted to this pane
  }
  let ran = 0
  for (const seq of pending(names)) {
    const base = `${dir}/${seq}`
    if (!(await io.claim(`${base}.json`, `${base}.taken`))) continue
    let result: { ok: boolean; error?: string }
    try {
      const msg = parseMessage(await io.read(`${base}.taken`))
      if ('error' in msg) result = { ok: false, error: msg.error }
      else {
        await io.run(msg.cmd, msg.args)
        result = { ok: true }
      }
    } catch (err) {
      result = { ok: false, error: errorText(err) }
    }
    try {
      await io.write(`${base}.done`, `${JSON.stringify(result)}\n`)
    } catch {
      // The poster times out to "running" (exit 6) and never types it again.
    }
    ran++
  }
  return ran
}

